"""Finite framebuffer QR visibility check. This is not a result channel."""

from __future__ import annotations

import ctypes
import fcntl
import mmap
import os
from pathlib import Path
import stat
import time


# Generated by qrencode 4.1.1 with -8 -l Q -v 2 --strict-version -m 4 -s 1.
# The 16-byte public token is unique to this single calibration image.
TOKEN = "D3EC66D328930EA1"
MATRIX = (
    "000000000000000000000000000000000",
    "000000000000000000000000000000000",
    "000000000000000000000000000000000",
    "000000000000000000000000000000000",
    "000011111110110100100011111110000",
    "000010000010010010001010000010000",
    "000010111010111100110010111010000",
    "000010111010101011000010111010000",
    "000010111010000000000010111010000",
    "000010000010110100011010000010000",
    "000011111110101010101011111110000",
    "000000000000111101011000000000000",
    "000001010111101000100111011010000",
    "000000011001100101000011000100000",
    "000000101011001001101001010110000",
    "000011010001110101010001100110000",
    "000000011010110000101011001010000",
    "000001101000101110110010011010000",
    "000010010110000011100101110110000",
    "000001000001111010011001010100000",
    "000011000010100011101111111110000",
    "000000000000101011111000100000000",
    "000011111110111111101010100110000",
    "000010000010100001101000111100000",
    "000010111010001010101111110110000",
    "000010111010111100110100100000000",
    "000010111010011111000101101010000",
    "000010000010110001001001100000000",
    "000011111110000001001101101110000",
    "000000000000000000000000000000000",
    "000000000000000000000000000000000",
    "000000000000000000000000000000000",
    "000000000000000000000000000000000",
)


class _Bitfield(ctypes.Structure):
    _fields_ = [("offset", ctypes.c_uint32), ("length", ctypes.c_uint32),
                ("msb_right", ctypes.c_uint32)]


class _VarScreenInfo(ctypes.Structure):
    _fields_ = [
        (name, ctypes.c_uint32) for name in (
            "xres", "yres", "xres_virtual", "yres_virtual", "xoffset", "yoffset",
            "bits_per_pixel", "grayscale",
        )
    ] + [(name, _Bitfield) for name in ("red", "green", "blue", "transp")] + [
        (name, ctypes.c_uint32) for name in (
            "nonstd", "activate", "height", "width", "accel_flags", "pixclock",
            "left_margin", "right_margin", "upper_margin", "lower_margin",
            "hsync_len", "vsync_len", "sync", "vmode", "rotate", "colorspace",
        )
    ] + [("reserved", ctypes.c_uint32 * 4)]


class _FixScreenInfo(ctypes.Structure):
    _fields_ = [
        ("id", ctypes.c_char * 16), ("smem_start", ctypes.c_ulong),
        ("smem_len", ctypes.c_uint32), ("type", ctypes.c_uint32),
        ("type_aux", ctypes.c_uint32), ("visual", ctypes.c_uint32),
        ("xpanstep", ctypes.c_uint16), ("ypanstep", ctypes.c_uint16),
        ("ywrapstep", ctypes.c_uint16), ("line_length", ctypes.c_uint32),
        ("mmio_start", ctypes.c_ulong), ("mmio_len", ctypes.c_uint32),
        ("accel", ctypes.c_uint32), ("capabilities", ctypes.c_uint16),
        ("reserved", ctypes.c_uint16 * 2),
    ]


def _screen_info(fd: int) -> tuple[_VarScreenInfo, _FixScreenInfo]:
    variable = bytearray(ctypes.sizeof(_VarScreenInfo))
    fixed = bytearray(ctypes.sizeof(_FixScreenInfo))
    fcntl.ioctl(fd, 0x4600, variable, True)  # FBIOGET_VSCREENINFO
    fcntl.ioctl(fd, 0x4602, fixed, True)  # FBIOGET_FSCREENINFO
    return _VarScreenInfo.from_buffer_copy(variable), _FixScreenInfo.from_buffer_copy(fixed)


def _pixel(info: _VarScreenInfo, brightness: int) -> bytes:
    if info.bits_per_pixel not in (16, 32) or info.grayscale or info.nonstd:
        raise ValueError("unsupported calibration framebuffer format")
    mask = 0
    pixel = 0
    for field in (info.red, info.green, info.blue):
        if (field.length < 1 or field.length > 16 or field.msb_right
                or field.offset + field.length > info.bits_per_pixel):
            raise ValueError("invalid calibration framebuffer color field")
        bits = ((1 << field.length) - 1) << field.offset
        if mask & bits:
            raise ValueError("overlapping calibration framebuffer color fields")
        mask |= bits
        pixel |= (brightness * ((1 << field.length) - 1) // 255) << field.offset
    if info.transp.length:
        if (info.transp.msb_right or info.transp.length > 16
                or info.transp.offset + info.transp.length > info.bits_per_pixel
                or mask & (((1 << info.transp.length) - 1) << info.transp.offset)):
            raise ValueError("invalid calibration framebuffer alpha field")
        pixel |= ((1 << info.transp.length) - 1) << info.transp.offset
    return pixel.to_bytes(info.bits_per_pixel // 8, "little")


def _render(framebuffer: mmap.mmap, variable: _VarScreenInfo,
            fixed: _FixScreenInfo, *, scale: int, brightness: int) -> None:
    if len(MATRIX) != 33 or any(len(row) != 33 or set(row) - {"0", "1"} for row in MATRIX):
        raise ValueError("invalid fixed calibration matrix")
    size = len(MATRIX) * scale
    if not 0 < size <= variable.xres or size > variable.yres:
        raise ValueError("calibration symbol does not fit the visible framebuffer")
    if (variable.xoffset + size > variable.xres_virtual
            or variable.yoffset + size > variable.yres_virtual):
        raise ValueError("calibration symbol exceeds virtual framebuffer")
    if fixed.visual != 2 or not 0 < fixed.smem_len <= 128 << 20:
        raise ValueError("unsupported calibration framebuffer memory")
    depth = variable.bits_per_pixel // 8
    if fixed.line_length < (variable.xoffset + size) * depth:
        raise ValueError("calibration framebuffer stride is too short")
    end = (variable.yoffset + size - 1) * fixed.line_length + (variable.xoffset + size) * depth
    if end > fixed.smem_len:
        raise ValueError("calibration symbol exceeds framebuffer memory")
    dark = _pixel(variable, 0)
    light = _pixel(variable, brightness)
    for row_index, bits in enumerate(MATRIX):
        row = b"".join((dark if bit == "1" else light) * scale for bit in bits)
        for dy in range(scale):
            start = ((variable.yoffset + row_index * scale + dy) * fixed.line_length
                     + variable.xoffset * depth)
            framebuffer[start:start + len(row)] = row


def run() -> dict[str, int]:
    """Draw four bounded contrast/scale variants, then let init reboot."""
    path = Path("/dev/fb0")
    fd = os.open(path, os.O_RDWR | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0))
    try:
        info = os.fstat(fd)
        if (not stat.S_ISCHR(info.st_mode) or os.major(info.st_rdev) != 29
                or os.minor(info.st_rdev) != 0):
            raise ValueError("calibration output is not a framebuffer device")
        variable, fixed = _screen_info(fd)
        if (variable.bits_per_pixel not in (16, 32) or fixed.visual != 2
                or not 0 < fixed.smem_len <= 128 << 20):
            raise ValueError("unsupported calibration framebuffer size or depth")
        with mmap.mmap(fd, fixed.smem_len, access=mmap.ACCESS_WRITE) as framebuffer:
            for scale, brightness in ((6, 180), (8, 180), (6, 255), (8, 255)):
                _render(framebuffer, variable, fixed, scale=scale, brightness=brightness)
                time.sleep(18)
        return {"xres": variable.xres, "yres": variable.yres,
                "bits_per_pixel": variable.bits_per_pixel, "line_length": fixed.line_length}
    finally:
        os.close(fd)
